describe('Email/Username Login Interchangeability', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with email or username interchangeably', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to log in with email
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify login request was made with email
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.request.body.email).to.equal('user@example.com');
    });

    // Verify successful login redirect
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome, user@example.com');

    // Clear email and attempt to log in with username
    cy.get('[data-testid="email-input"]').clear();
    cy.get('[data-testid="username-input"]').type('user123');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify login request was made with username
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.request.body.username).to.equal('user123');
    });

    // Verify successful login redirect
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome, user123');
  });

  it('should display error when email or username is invalid', () => {
    // Attempt to log in with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid email address');

    // Clear invalid email and attempt to log in with invalid username
    cy.get('[data-testid="email-input"]').clear();
    cy.get('[data-testid="username-input"]').type('invalid-username');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid username');
  });
});
